changeSet.sql:
CREATE TABLE verbrauchskosten_preis (
 verbrauchskosten_id BIGINT NOT NULL REFERENCES verbrauchskosten(id) ON DELETE CASCADE,
 gueltig_von DATE NOT NULL, gueltig_bis DATE, preis NUMERIC(10,2) NOT NULL,
 PRIMARY KEY (verbrauchskosten_id, gueltig_von),
 CHECK (preis >= 0), CHECK (gueltig_bis IS NULL OR gueltig_bis >= gueltig_von)
);
INSERT INTO verbrauchskosten_preis (verbrauchskosten_id, gueltig_von, preis)
 SELECT id, DATE '0001-01-01', preis FROM verbrauchskosten;
